import UIKit

@main
class AppDelegate: UIResponder, UIApplicationDelegate {
    func application(_ application: UIApplication, didFinishLaunchingWithOptions launchOptions: [UIApplication.LaunchOptionsKey: Any]?) -> Bool {
        return true
    }
}

import XCTest

final class TapHarnessUITests: XCTestCase {
    let app = XCUIApplication(bundleIdentifier: "im.vector.app")

    override func setUpWithError() throws {
        continueAfterFailure = false
    }

    func testRunScript() throws {
        app.activate()
        Thread.sleep(forTimeInterval: 2)

        let fm = FileManager.default
        let tmp = fm.temporaryDirectory
        let scriptURL = tmp.appendingPathComponent("script.json")

        guard let data = fm.contents(atPath: scriptURL.path),
              let steps = try? JSONSerialization.jsonObject(with: data) as? [[String: Any]] else {
            try app.debugDescription.write(toFile: tmp.appendingPathComponent("hierarchy.txt").path, atomically: true, encoding: .utf8)
            return
        }

        for step in steps {
            try runStep(step, tmp: tmp)
        }
        try app.debugDescription.write(toFile: tmp.appendingPathComponent("hierarchy.txt").path, atomically: true, encoding: .utf8)
    }

    func runStep(_ step: [String: Any], tmp: URL) throws {
        let op = step["op"] as? String ?? ""
        switch op {
        case "wait":
            Thread.sleep(forTimeInterval: (step["t"] as? Double) ?? 1.0)
        case "dump":
            let name = (step["name"] as? String) ?? "hierarchy"
            try app.debugDescription.write(toFile: tmp.appendingPathComponent(name + ".txt").path, atomically: true, encoding: .utf8)
        case "tapId":
            let id = step["id"] as! String
            let el = app.descendants(matching: .any)[id].firstMatch
            XCTAssertTrue(el.waitForExistence(timeout: 5), "tapId not found: \(id)")
            el.tap()
        case "tapLabel":
            let label = step["label"] as! String
            let q = app.descendants(matching: .any).matching(NSPredicate(format: "label == %@", label))
            let el = q.firstMatch
            XCTAssertTrue(el.waitForExistence(timeout: 5), "tapLabel not found: \(label)")
            el.tap()
        case "tapXY":
            let x = step["x"] as! Double
            let y = step["y"] as! Double
            app.coordinate(withNormalizedOffset: CGVector(dx: x, dy: y)).tap()
        case "swipe":
            let dir = step["dir"] as? String ?? "up"
            switch dir {
            case "up": app.swipeUp()
            case "down": app.swipeDown()
            case "left": app.swipeLeft()
            default: app.swipeRight()
            }
        case "screenshot":
            let name = (step["name"] as? String) ?? "shot"
            let shot = app.screenshot()
            try shot.pngRepresentation.write(to: tmp.appendingPathComponent(name + ".png"))
        default:
            break
        }
        Thread.sleep(forTimeInterval: 0.8)
    }
}

